cat > app/src/timeout.js <<'EOF'
/** Parses a --timeout value: whole milliseconds, greater than zero. */
export function parseTimeout(text) {
  if (!/^-?\d+$/.test(text)) {
    throw new RangeError(`invalid timeout: ${text}`);
  }
  const ms = Number(text);
  if (ms <= 0) throw new RangeError(`timeout must be above zero: ${text}`);
  return ms;
}
EOF

cat > app/test/positive.test.js <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { parseTimeout } from "../src/timeout.js";

test("rejects zero and negative values", () => {
  assert.throws(() => parseTimeout("0"), RangeError);
  assert.throws(() => parseTimeout("-5"), RangeError);
});
EOF
